def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    left_w = 0
    while left_w < w and grid[0][left_w] == bg:
        left_w += 1

    out = [row[:left_w] for row in grid]

    # Collect the shapes and colors of the objects to the right.
    objects = []
    by_color = {}
    for r in range(h):
        for c in range(left_w, w):
            color = grid[r][c]
            if color != 0:
                by_color.setdefault(color, []).append((r, c))

    for color, cells in by_color.items():
        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        shape = frozenset((r - minr, c - minc) for r, c in cells)
        objects.append((maxr - minr + 1, maxc - minc + 1, shape, color))

    separators = [
        r for r in range(h)
        if all(grid[r][c] == bg for c in range(left_w))
    ]

    for top, bottom in zip(separators, separators[1:]):
        rows = list(range(top + 1, bottom))
        cols = list(range(1, left_w - 1))
        cells = [(r, c) for r in rows for c in cols if grid[r][c] != bg]
        if not cells:
            continue

        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        shape = frozenset((r - minr, c - minc) for r, c in cells)
        sh, sw = maxr - minr + 1, maxc - minc + 1

        for oh, ow, object_shape, color in objects:
            if (sh, sw, shape) == (oh, ow, object_shape):
                for r, c in cells:
                    out[r][c] = color
                break

    return out
